// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;
    function setUp() public { c = new Proxy(); }
    function testFuzz_property(bytes calldata data) public {
        vm.assume(data.length > 0);
        StateModifier helper = new StateModifier();
        bool success = true;
        try c.forward(address(helper), data) { success = true; } catch { success = false; }
        assertTrue(success);
    }
}

contract StateModifier {
    uint256 public x;
    fallback(bytes calldata _data) external payable returns (bytes memory) {
        x = 1;
        return abi.encode(x);
    }
}
